1	package net.officefloor.hq.app.invoices;
2	
3	import java.math.BigDecimal;
4	import java.time.LocalDate;
5	import java.util.List;
6	import net.officefloor.hq.app.Audit;
7	import org.springframework.jdbc.core.JdbcTemplate;
8	import org.springframework.jdbc.core.RowMapper;
9	import org.springframework.stereotype.Service;
10	import org.springframework.transaction.annotation.Transactional;
11	
12	/**
13	 * Business logic for invoices. Invoices are always viewed in the context of their project, so the
14	 * list is scoped by project id. The derived total the UI shows is computed by the front-end from the
15	 * returned rows; this service just surfaces the project's invoices in a stable order. Marking an
16	 * invoice paid flips its status and records an audit entry so the action can be checked later.
17	 */
18	@Service
19	public class InvoiceService {
20	
21	    // An invoice's amount minus whatever has been paid against it is what is still left to pay.
22	    private static final String DUE_AWARE_SELECT =
23	            "SELECT i.id, i.project_id, i.amount, i.status, i.issued_date, i.due_date, "
24	                    + "i.amount - COALESCE((SELECT SUM(p.amount) FROM payments p "
25	                    + "WHERE p.invoice_id = i.id), 0) AS due_amount FROM invoices i ";
26	
27	    private static final RowMapper<InvoiceView> INVOICE_MAPPER = (rs, i) -> {
28	        BigDecimal amount = rs.getBigDecimal("amount");
29	        BigDecimal dueAmount = rs.getBigDecimal("due_amount");
30	        return new InvoiceView(rs.getLong("id"), rs.getLong("project_id"), amount,
31	                deriveStatus(rs.getString("status"), amount, dueAmount),
32	                rs.getDate("issued_date").toLocalDate().toString(),
33	                rs.getDate("due_date").toLocalDate().toString(), dueAmount);
34	    };
35	
36	    /**
37	     * The status we show is worked out from the payments, not flipped by hand: an invoice reads PAID
38	     * once its payments cover the amount, PARTIAL once some (but not all) has been paid, and otherwise
39	     * keeps its stored lifecycle status (DRAFT/SENT).
40	     */
41	    private static String deriveStatus(String stored, BigDecimal amount, BigDecimal dueAmount) {
42	        BigDecimal paid = amount.subtract(dueAmount);
43	        if (paid.signum() <= 0) {
44	            return stored;
45	        }
46	        return dueAmount.signum() <= 0 ? "PAID" : "PARTIAL";
47	    }
48	
49	    private final InvoiceRepository repository;
50	    private final LineItemRepository lineItemRepository;
51	    private final PaymentRepository paymentRepository;
52	    private final JdbcTemplate jdbc;
53	    private final Audit audit;
54	
55	    public InvoiceService(InvoiceRepository repository, LineItemRepository lineItemRepository,
56	            PaymentRepository paymentRepository, JdbcTemplate jdbc, Audit audit) {
57	        this.repository = repository;
58	        this.lineItemRepository = lineItemRepository;
59	        this.paymentRepository = paymentRepository;
60	        this.jdbc = jdbc;
61	        this.audit = audit;
62	    }
63	
64	    /** Every invoice across all projects; narrowed to a single lifecycle stage when {@code status} is given. */
65	    @Transactional(readOnly = true)
66	    public List<AllInvoiceView> listAll(String status) {
67	        RowMapper<AllInvoiceView> mapper = (rs, i) -> new AllInvoiceView(rs.getLong("id"),
68	                rs.getString("project_name"), rs.getBigDecimal("amount"), rs.getString("status"));
69	        String base = "SELECT i.id, i.amount, i.status, p.name AS project_name "
70	                + "FROM invoices i JOIN projects p ON i.project_id = p.id ";
71	        if (status == null || status.isBlank()) {
72	            return jdbc.query(base + "ORDER BY i.id ASC", mapper);
73	        }
74	        return jdbc.query(base + "WHERE i.status = ? ORDER BY i.id ASC", mapper, status.trim());
75	    }
76	
77	    @Transactional(readOnly = true)
78	    public List<InvoiceView> listForProject(Long projectId) {
79	        return jdbc.query(
80	                DUE_AWARE_SELECT + "WHERE i.project_id = ? ORDER BY i.id ASC",
81	                INVOICE_MAPPER, projectId);
82	    }
83	
84	    @Transactional(readOnly = true)
85	    public List<InvoiceView> listForProjectByDueDate(Long projectId) {
86	        return jdbc.query(
87	                DUE_AWARE_SELECT + "WHERE i.project_id = ? ORDER BY i.due_date ASC, i.id ASC",
88	                INVOICE_MAPPER, projectId);
89	    }
90	
91	    @Transactional
92	    public InvoiceView create(Long projectId, BigDecimal amount) {
93	        if (projectId == null) {
94	            throw new IllegalArgumentException("An invoice requires a project");
95	        }
96	        if (amount == null) {
97	            throw new IllegalArgumentException("An invoice requires an amount");
98	        }
99	        if (amount.signum() <= 0) {
100	            throw new IllegalArgumentException("An invoice amount must be greater than zero");
101	        }
102	        Invoice invoice = new Invoice();
103	        invoice.setProjectId(projectId);
104	        invoice.setAmount(amount);
105	        // A new invoice goes out today and is due 30 days later.
106	        LocalDate issued = LocalDate.now();
107	        invoice.setIssuedDate(issued);
108	        invoice.setDueDate(issued.plusDays(30));
109	        Invoice saved = repository.save(invoice);
110	        // A brand-new invoice has had nothing paid against it yet, so the whole amount is due.
111	        return new InvoiceView(saved.getId(), saved.getProjectId(), saved.getAmount(),
112	                saved.getStatus(), saved.getIssuedDate().toString(), saved.getDueDate().toString(),
113	                saved.getAmount());
114	    }
115	
116	    @Transactional
117	    public InvoiceView send(Long invoiceId) {
118	        if (invoiceId == null) {
119	            throw new IllegalArgumentException("An invoice id is required");
120	        }
121	        InvoiceView current = find(invoiceId);
122	        if (!"DRAFT".equals(current.getStatus())) {
123	            throw new IllegalStateException("Only a draft invoice can be sent");
124	        }
125	        jdbc.update("UPDATE invoices SET status = 'SENT' WHERE id = ?", invoiceId);
126	        InvoiceView invoice = find(invoiceId);
127	        audit.record("INVOICE_SENT id=" + invoice.getId() + " amount="
128	                + invoice.getAmount().setScale(2));
129	        return invoice;
130	    }
131	
132	    @Transactional
133	    public InvoiceView pay(Long invoiceId) {
134	        if (invoiceId == null) {
135	            throw new IllegalArgumentException("An invoice id is required");
136	        }
137	        InvoiceView current = find(invoiceId);
138	        // Payment is only allowed once an invoice has been sent.
139	        if (!"SENT".equals(current.getStatus())) {
140	            throw new IllegalStateException("An invoice can only be paid once it has been sent");
141	        }
142	        jdbc.update("UPDATE invoices SET status = 'PAID' WHERE id = ?", invoiceId);
143	        InvoiceView invoice = find(invoiceId);
144	        audit.record("INVOICE_PAID id=" + invoice.getId() + " amount="
145	                + invoice.getAmount().setScale(2));
146	        return invoice;
147	    }
148	
149	    /** The line items of an invoice, in the order they were added. */
150	    @Transactional(readOnly = true)
151	    public List<LineItemView> listLineItems(Long invoiceId) {
152	        return jdbc.query(
153	                "SELECT id, invoice_id, description, qty, unit_price FROM line_items WHERE invoice_id = ? ORDER BY id ASC",
154	                (rs, i) -> new LineItemView(rs.getLong("id"), rs.getLong("invoice_id"),
155	                        rs.getString("description"), rs.getInt("qty"),
156	                        rs.getBigDecimal("unit_price")),
157	                invoiceId);
158	    }
159	
160	    /**
161	     * Add one line item to an invoice, then re-derive the invoice's amount as the sum of each line's
162	     * quantity times unit price so the stored total stays in step. Returns the invoice's line items.
163	     */
164	    @Transactional
165	    public List<LineItemView> addLineItem(Long invoiceId, NewLineItem body) {
166	        if (invoiceId == null) {
167	            throw new IllegalArgumentException("An invoice id is required");
168	        }
169	        if (body == null || body.getDescription() == null || body.getDescription().isBlank()) {
170	            throw new IllegalArgumentException("A line item requires a description");
171	        }
172	        if (body.getQty() == null || body.getQty() <= 0) {
173	            throw new IllegalArgumentException("A line item requires a quantity greater than zero");
174	        }
175	        if (body.getUnitPrice() == null || body.getUnitPrice().signum() < 0) {
176	            throw new IllegalArgumentException("A line item requires a unit price that is not negative");
177	        }
178	        LineItem lineItem = new LineItem();
179	        lineItem.setInvoiceId(invoiceId);
180	        lineItem.setDescription(body.getDescription());
181	        lineItem.setQty(body.getQty());
182	        lineItem.setUnitPrice(body.getUnitPrice());
183	        lineItemRepository.save(lineItem);
184	        jdbc.update(
185	                "UPDATE invoices SET amount = COALESCE((SELECT SUM(qty * unit_price) FROM line_items WHERE invoice_id = ?), 0) WHERE id = ?",
186	                invoiceId, invoiceId);
187	        return listLineItems(invoiceId);
188	    }
189	
190	    /**
191	     * Remove one line item from an invoice, then re-derive the invoice's amount as the sum of each
192	     * remaining line's quantity times unit price so the stored total stays in step. Returns the
193	     * invoice's remaining line items.
194	     */
195	    @Transactional
196	    public List<LineItemView> removeLineItem(Long invoiceId, Long lineItemId) {
197	        if (invoiceId == null) {
198	            throw new IllegalArgumentException("An invoice id is required");
199	        }
200	        if (lineItemId == null) {
201	            throw new IllegalArgumentException("A line item id is required");
202	        }
203	        jdbc.update("DELETE FROM line_items WHERE id = ? AND invoice_id = ?", lineItemId, invoiceId);
204	        jdbc.update(
205	                "UPDATE invoices SET amount = COALESCE((SELECT SUM(qty * unit_price) FROM line_items WHERE invoice_id = ?), 0) WHERE id = ?",
206	                invoiceId, invoiceId);
207	        return listLineItems(invoiceId);
208	    }
209	
210	    /** The payments a client has made on an invoice, in the order they were recorded. */
211	    @Transactional(readOnly = true)
212	    public List<PaymentView> listPayments(Long invoiceId) {
213	        return jdbc.query(
214	                "SELECT id, invoice_id, amount, paid_date FROM payments WHERE invoice_id = ? ORDER BY id ASC",
215	                (rs, i) -> new PaymentView(rs.getLong("id"), rs.getLong("invoice_id"),
216	                        rs.getBigDecimal("amount"), rs.getDate("paid_date").toLocalDate().toString()),
217	                invoiceId);
218	    }
219	
220	    /** Record one payment a client has made against an invoice. Returns the invoice's payments. */
221	    @Transactional
222	    public List<PaymentView> addPayment(Long invoiceId, NewPayment body) {
223	        if (invoiceId == null) {
224	            throw new IllegalArgumentException("An invoice id is required");
225	        }
226	        if (body == null || body.getAmount() == null || body.getAmount().signum() <= 0) {
227	            throw new IllegalArgumentException("A payment requires an amount greater than zero");
228	        }
