-- Second domain table: projects a user does for a client. Each project belongs to one client.
CREATE TABLE projects (
    id        BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name      VARCHAR(255) NOT NULL,
    client_id BIGINT       NOT NULL REFERENCES clients(id)
);
-- Third domain table: invoices raised against a project. Each invoice belongs to one project and
-- carries a money amount (two decimal places).
CREATE TABLE invoices (
    id         BIGINT         GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    project_id BIGINT         NOT NULL REFERENCES projects(id),
    amount     NUMERIC(12, 2) NOT NULL
);
-- An invoice's amount is now DERIVED: it is the sum of its line items (quantity times unit price).
-- A newly raised invoice with no line items yet is worth $0.00, so the old "amount strictly
-- positive" invariant no longer holds. Drop that check; the amount column now caches the derived
-- total and is kept in step whenever a line item is added.
ALTER TABLE invoices DROP CONSTRAINT chk_invoices_amount_positive;
ALTER TABLE invoices ALTER COLUMN amount SET DEFAULT 0;
-- Projects are archived, not deleted: a flag tucks a project away so it drops off the lists while the
-- row (and everything hanging off it) is retained. Defaults FALSE so every existing project stays
-- visible; archiving flips it to TRUE.
ALTER TABLE projects ADD COLUMN archived BOOLEAN NOT NULL DEFAULT FALSE;
-- Projects now carry a lifecycle status: whether the work is ACTIVE, ON_HOLD or FINISHED. New
-- projects start ACTIVE; the default keeps every existing project visible as active work.
ALTER TABLE projects ADD COLUMN status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE';

